#include <cstdio>

int main() {
    long long n;
    if (scanf("%lld", &n) != 1) return 0;
    const long long MOD = 1000000007LL;
    long long t = 0;
    // For fixed j: q full residue cycles (sum j(j-1)/2 each) plus residues 1..r.
    for (long long j = 1; j <= n; j++) {
        long long q = n / j, r = n % j;
        long long s = q * j * (j - 1) / 2 + r * (r + 1) / 2;
        t = (t + s) % MOD;
    }
    printf("%lld\n", 2 * t % MOD);
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        long n = new Scanner(System.in).nextLong();
        final long MOD = 1_000_000_007L;
        long t = 0;
        // For fixed j: q full residue cycles (sum j(j-1)/2 each) plus residues 1..r.
        for (long j = 1; j <= n; j++) {
            long q = n / j, r = n % j;
            long s = q * j * (j - 1) / 2 + r * (r + 1) / 2;
            t = (t + s) % MOD;
        }
        System.out.println(2 * t % MOD);
    }
}

